query GeUnreadMessageCounts($input: GetUnreadCountRequest!) {
  messageApi {
    getUnreadCount(input: $input) {
      count
    }
  }
}

query TodayIssues($cancelledOrdersCountParams: OrdersCountReq!, $delayedOrdersCountParams: OrdersCountReq!, $issuesMetricParams: DateRangeVendorsMetricRequest!) {
  orders {
    cancelledOrders: ordersCount(input: $cancelledOrdersCountParams) {
      amount
      __typename
    }
    delayedOrders: ordersCount(input: $delayedOrdersCountParams) {
      amount
      __typename
    }
    __typename
  }
  reports {
    issuesMetric(input: $issuesMetricParams) {
      oneStarRatingsCount
      oneStarRatingsDetails {
        global_vendor_code
        count
        __typename
      }
      __typename
    }
    __typename
  }
}

query SalesOverviewByTime($params: DateRangeWithPrecisionVendorsReportRequest!) {
  salesOverview {
    salesByTime(input: $params) {
      order_count
      revenue
      details {
        order_count
        revenue
        milestone
        __typename
      }
      __typename
    }
    __typename
  }
}

query GetRecommendations($input: RecommendationsReq!) {
  recommendations(input: $input) {
    vendorId
    type {
      name
      ads
      __typename
    }
    completed
    status
    statusReason
    version
    priority
    metadata {
      key
      value
      __typename
    }
    opsInsights {
      cancellationReasons {
        reason
        lostOrders
        lostRevenue
        __typename
      }
      offlineRateReasons {
        reason
        durationHours
        __typename
      }
      __typename
    }
    framework
    icon
    __typename
  }
}

