query ListPayouts($params: ListPayoutsRequest!) {
  finances {
    listPayouts(input: $params) {
      nextPageToken
      prevPageToken
      payouts {
        payoutId: id
        payoutAmount: netPayout
        payoutCurrency: currency
        payoutOrders: ordersCount
        at: paymentDateLocal
        status: payoutStatus
        payoutAttachments: attachments
        payoutAccount: account {
          grid
          billingParentId
          chainId
          __typename
        }
        invoices {
          invoiceId: id
          invoiceAmount: totalPayout
          invoiceCurrency: currency
          invoiceOrders: ordersCount
          processedDate
          invoiceAttachments: attachments
          period: earningsPeriod {
            from: invoiceStartDate
            to: invoiceEndDate
            __typename
          }
          invoiceAccount: account {
            grid
            billingParentId
            chainId
            __typename
          }
          __typename
        }
        __typename
      }
      __typename
    }
    __typename
  }
}
